const Show = require('../models/Show');
const Movie = require('../models/Movie');

// @desc  Create a new show
// @route POST /api/admin/shows
const createShow = async (req, res, next) => {
  try {
    const { movieId, showTime, screen } = req.body;

    if (!movieId || !showTime) {
      return res.status(400).json({ success: false, message: 'movieId and showTime are required' });
    }

    const movie = await Movie.findById(movieId);
    if (!movie) return res.status(404).json({ success: false, message: 'Movie not found' });

    // Seats will be auto-generated by the pre-save hook
    const show = new Show({
      movie: movieId,
      showTime: new Date(showTime),
      screen: screen || 'Screen 1',
      seats: [], // will be filled by pre-save
    });

    await show.save();
    await show.populate('movie', 'title duration genre posterUrl');

    res.status(201).json({ success: true, message: 'Show created with 30 seats', data: show });
  } catch (err) {
    next(err);
  }
};

// @desc  Get all shows (admin), optionally filter by movieId
// @route GET /api/admin/shows?movieId=xxx
const getAllShowsAdmin = async (req, res, next) => {
  try {
    const { movieId, page = 1, limit = 50 } = req.query;
    const query = movieId ? { movie: movieId } : {};

    const total = await Show.countDocuments(query);
    const shows = await Show.find(query)
      .populate('movie', 'title duration genre posterUrl')
      .sort({ showTime: 1 })
      .skip((page - 1) * limit)
      .limit(Number(limit));

    res.json({
      success: true,
      data: shows,
      pagination: { page: Number(page), limit: Number(limit), total },
    });
  } catch (err) {
    next(err);
  }
};

// @desc  Delete a show
// @route DELETE /api/admin/shows/:id
const deleteShow = async (req, res, next) => {
  try {
    const show = await Show.findByIdAndDelete(req.params.id);
    if (!show) return res.status(404).json({ success: false, message: 'Show not found' });
    res.json({ success: true, message: 'Show deleted' });
  } catch (err) {
    next(err);
  }
};

module.exports = { createShow, getAllShowsAdmin, deleteShow };
